#!/usr/bin/env bash
# step76 — Customer accounts Phase 1: sign-up / login / logout / email verification.
# Adds: customers + customer_tokens tables, routes/account.js, 4 account views,
# a shared auth style, account links in header + mobile drawer, and a
# res.locals.customer middleware. Passwords hashed with built-in crypto.scrypt
# (no new npm dep). Verification code sent via the existing lib/mailer.
# Fully idempotent; any failure rolls back server.js + both shell partials.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step76-$TS
mkdir -p "$BAK/routes" "$BAK/views/partials"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/views/partials/store_top.ejs" "$BAK/views/partials/store_top.ejs"
cp "$APP/views/partials/store_bottom.ejs" "$BAK/views/partials/store_bottom.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/views/partials/store_top.ejs" "$APP/views/partials/store_top.ejs"; cp "$BAK/views/partials/store_bottom.ejs" "$APP/views/partials/store_bottom.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> migrate: customers + customer_tokens (as app DB user)"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const pool = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS, max:4 });
(async()=>{
  await pool.query(`CREATE TABLE IF NOT EXISTS customers(
    id serial PRIMARY KEY, name text NOT NULL, email text NOT NULL,
    email_verified boolean NOT NULL DEFAULT false,
    wa_number text, wa_verified boolean NOT NULL DEFAULT false,
    pass_hash text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(), last_login timestamptz)`);
  await pool.query(`CREATE UNIQUE INDEX IF NOT EXISTS customers_email_uidx ON customers(lower(email))`);
  await pool.query(`CREATE TABLE IF NOT EXISTS customer_tokens(
    id serial PRIMARY KEY,
    customer_id integer NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    kind text NOT NULL, code text NOT NULL, tries integer NOT NULL DEFAULT 0,
    used boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now())`);
  await pool.query(`CREATE INDEX IF NOT EXISTS customer_tokens_cust_idx ON customer_tokens(customer_id, kind)`);
  const n = (await pool.query(`SELECT count(*)::int c FROM customers`)).rows[0].c;
  console.log('   customers ready; existing rows: '+n);
  await pool.end();
})().catch(e=>{ console.error('MIGRATION FAIL: '+e.message); process.exit(1); });
NODE

echo "==> write new files"
w(){ mkdir -p "$(dirname "$APP/$1")"; base64 -d > "$APP/$1"; }
w routes/account.js <<'B64'

B64
w views/account/login.ejs <<'B64'

B64
w views/account/signup.ejs <<'B64'

B64
w views/account/verify_email.ejs <<'B64'

B64
w views/account/dashboard.ejs <<'B64'

B64
w views/partials/auth_style.ejs <<'B64'

B64

echo "==> patch server.js (customer middleware + account router)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8'); let ch=0;
const sess="app.use(session({ secret: process.env.SESSION_SECRET, resave: false, saveUninitialized: false }));";
if(s.indexOf('res.locals.customer')<0){
  if(s.indexOf(sess)<0){ console.error('!! session anchor not found'); process.exit(2); }
  s=s.replace(sess, sess+"\napp.use((req, res, next) => { res.locals.customer = (req.session && req.session.customer) || null; next(); });");
  ch++;
}
const catMount="const categoryRouter = require('./routes/category')(pool);\napp.use('/category', categoryRouter);";
if(s.indexOf('routes/account')<0){
  if(s.indexOf(catMount)<0){ console.error('!! category mount anchor not found'); process.exit(3); }
  s=s.replace(catMount, catMount+"\nconst accountRouter = require('./routes/account')(pool);\napp.use('/', accountRouter);");
  ch++;
}
if(ch){ fs.writeFileSync(f,s); console.log('   server.js patched ('+ch+' change(s))'); } else { console.log('   server.js already patched'); }
NODE

echo "==> patch header (account link)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/views/partials/store_top.ejs'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('hd-acct')>=0){ console.log('   header already patched'); }
else {
  const anc='<button class="icon-btn burger" id="burger"';
  if(s.indexOf(anc)<0){ console.error('!! burger anchor not found'); process.exit(4); }
  const acct='<a class="region hd-acct" href="<%= locals.customer ? \'/account\' : \'/login\' %>" title="<%= locals.customer ? \'My account\' : \'Sign in\' %>" style="text-decoration:none;gap:7px">'
   +'<svg class="ic ic-sm" viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.6-7 8-7s8 3 8 7"/></svg>'
   +'<span><%= locals.customer ? String(customer.name||\'Account\').split(\' \')[0] : \'Sign in\' %></span></a>\n      ';
  s=s.replace(anc, acct+anc); fs.writeFileSync(f,s); console.log('   header patched');
}
NODE

echo "==> patch mobile drawer (account link)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/views/partials/store_bottom.ejs'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('drawer-acct')>=0){ console.log('   drawer already patched'); }
else {
  const anc='<button class="btn btn-ghost" id="drawerCurrency"';
  if(s.indexOf(anc)<0){ console.error('!! drawer anchor not found'); process.exit(5); }
  const acct='<a class="btn btn-ghost drawer-acct" href="<%= locals.customer ? \'/account\' : \'/login\' %>" style="width:100%;justify-content:center;text-decoration:none"><%= locals.customer ? \'My account\' : \'Sign in / Create account\' %></a>\n    ';
  s=s.replace(anc, acct+anc); fs.writeFileSync(f,s); console.log('   drawer patched');
}
NODE

echo "==> node --check"; node --check "$APP/routes/account.js"; node --check "$APP/server.js"
echo "==> ejs compile (new + patched views)"
node <<'NODE'
const ejs=require('ejs'),fs=require('fs');
['views/account/login.ejs','views/account/signup.ejs','views/account/verify_email.ejs','views/account/dashboard.ejs','views/partials/auth_style.ejs','views/partials/store_top.ejs','views/partials/store_bottom.ejs'].forEach(v=>{ ejs.compile(fs.readFileSync('/opt/gsz/'+v,'utf8'),{filename:'/opt/gsz/'+v}); console.log('   compiled '+v); });
NODE

echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q 'Create an account' <<<"$(curl -s -m 10 http://127.0.0.1:3900/login || true)" || { echo "!! /login not rendering"; false; }
grep -q 'Create account' <<<"$(curl -s -m 10 http://127.0.0.1:3900/signup || true)" || { echo "!! /signup not rendering"; false; }
CODE=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/account || true)
echo "   /account (no session) -> HTTP $CODE"
[ "$CODE" = "302" ] || { echo "!! /account should redirect to /login when signed out"; false; }
trap - ERR
echo "==> step76 OK — customer accounts + email verification live. Backup: $BAK"
echo "   Try:  /signup   /login   /account   (account link now in header + menu)"
